function backupPassword(repeat){return new Promise(resolve=>{let dialog=el('dialog'),form=el('form'),a=el('input'),b=el('input');a.type=b.type='password';a.autocomplete=b.autocomplete=repeat?'new-password':'current-password';a.required=true;let label=el('label','Hasło kopii');label.append(a);form.append(label);if(repeat){let l=el('label','Powtórz hasło (min. 12 znaków)');b.required=true;l.append(b);form.append(l)}let ok=el('button','Zatwierdź'),cancel=el('button','Anuluj');cancel.type='button';form.append(ok,cancel);dialog.append(form);document.body.append(dialog);let result=null;form.onsubmit=e=>{e.preventDefault();if(repeat&&(a.value.length<12||a.value!==b.value)){alert('Hasła muszą być identyczne i mieć minimum 12 znaków.');return}result=a.value;dialog.close()};cancel.onclick=()=>dialog.close();dialog.onclose=()=>{a.value=b.value='';dialog.remove();resolve(result)};dialog.showModal()})}
