function chosenDeadline(){let mode=$('honor').value;if(mode==='day')return endToday();let d=new Date();if(mode==='week'){d.setDate(d.getDate()+(7-d.getDay())%7);d.setHours(24,0,0,0);return +d}let v=$('dueDate').value;if(!v)return NaN;d=new Date(v+'T00:00:00');d.setHours(24,0,0,0);return +d}
function activeOffer(i){return data.quests.some(q=>q.type==='contract'&&q.name===templates[i][0]&&!completion(q))||data.quests.some(q=>q.type==='contract'&&q.name===templates[i][0]&&completion(q)&&day(completion(q).time)===day())||events().some(x=>x.name===templates[i][0]&&day(x.time)===day())}
