function tick(){if(restoring)return;if(settleExpired()){if($('contractDetail').open)$('contractDetail').close();render()}for(let e of document.querySelectorAll('[data-deadline]')){let n=Math.max(0,Math.ceil((+e.dataset.deadline-Date.now())/1000));e.textContent='⌛ '+[Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(x=>String(x).padStart(2,'0')).join(':');e.classList.toggle('urgent',n<3600)}}
